{
     "title": "CSCI-243: The Mechanics of Programming",
     "learningObjectives": [
       "Define the core components of program structure and execution mechanics.",
       "Explain the program translation process from source code to executable binary.",
       "Identify key security and performance considerations in program design."
     ],
     "beats": [
       {
         "title": "Introduction to Program Structure",
         "claim": "Programs are organized into modules that define distinct units of code and data.",
         "example": "A C program divides functionality into functions and global variables.",
         "visualDirection": "Display a block diagram showing a main function calling three sub-functions with a shared data structure.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Execution Mechanics Overview",
         "claim": "Execution follows a sequential flow controlled by conditional statements and loops.",
         "example": "A for-loop iterates through an array, updating a running total each cycle.",
         "visualDirection": "Show a flowchart with a start node, a loop diamond, and exit arrows based on a boolean condition.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Memory Management Basics",
         "claim": "Variables occupy specific memory locations that the processor accesses during runtime.",
         "example": "An integer variable stores a fixed-size binary representation in RAM.",
         "visualDirection": "Illustrate a memory map with labeled addresses, data types, and pointer offsets.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Program Translation Process",
         "claim": "Source code undergoes compilation, linking, and assembly to produce an executable binary.",
         "example": "A compiler translates C syntax into machine instructions for the target CPU architecture.",
         "visualDirection": "Present a pipeline diagram showing source code, preprocessor, compiler, linker, and final executable.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Operating System Integration",
         "claim": "The operating system manages resource allocation and provides system calls for program execution.",
         "example": "A file I/O operation requests disk access through an OS kernel interface.",
         "visualDirection": "Draw a layered diagram with application code, OS API, and kernel resource managers.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Security Design Principles",
         "claim": "Security depends on the complete protocol and implementation, not only an algorithm name.",
         "example": "Using AES-256 with proper key management ensures confidentiality against known attacks.",
         "visualDirection": "Show a key lifecycle diagram covering generation, distribution, storage, and revocation.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Performance Optimization Strategies",
         "claim": "Performance issues in program design require careful analysis of time and space complexity.",
         "example": "Replacing nested loops with hash maps reduces average lookup time from O(n²) to O(1).",
         "visualDirection": "Display a comparison chart of algorithmic time complexity across different data structures.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Secure Development Practices",
         "claim": "Security requirements should be tracked throughout development to prevent vulnerabilities.",
         "example": "Maintaining a threat model document updates trust boundaries as the codebase evolves.",
         "visualDirection": "Present a checklist template with fields for asset, threat, control, and residual risk.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Verification and Testing Methods",
         "claim": "Verification provides evidence that selected practices and controls were performed correctly.",
         "example": "Static analysis tools scan source code for buffer overflows before compilation.",
         "visualDirection": "Show a testing workflow diagram linking unit tests, integration tests, and security scans.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Program design must balance structure, execution efficiency, and security requirements.",
         "example": "A secure, performant module validates inputs, manages memory safely, and follows established standards.",
         "visualDirection": "Display a three-column matrix evaluating code against structure, performance, and security criteria.",
         "sourceIds": ["nist-cryptographic-standards", "nist-ssdf"]
       }
     ]
   }
